import 'package:flutter/material.dart';import 'package:get/get.dart';import '../../../controllers/profile_controller.dart';import '../../../controllers/auth_controller.dart';import '../../../app/routes/app_routes.dart';
class ProfileScreen extends GetView<ProfileController>{const ProfileScreen({super.key});@override Widget build(BuildContext context){final auth=Get.find<AuthController>();final name=controller.nameInput;final phone=controller.phoneInput;return Scaffold(appBar:AppBar(title:const Text('My profile')),body:Obx(()=>!auth.isLoggedIn?Center(child:FilledButton(onPressed:()=>Get.toNamed(AppRoutes.login),child:const Text('Sign in'))):controller.loading.value?const Center(child:CircularProgressIndicator()):ListView(padding:const EdgeInsets.all(20),children:[const CircleAvatar(radius:36,child:Icon(Icons.person,size:38)),const SizedBox(height:16),Text(auth.user.value?.email??'',textAlign:TextAlign.center),const SizedBox(height:20),TextField(controller:name,decoration:InputDecoration(labelText:'Full name',hintText:controller.profile['name']?.toString()??auth.user.value?.name)),const SizedBox(height:12),TextField(controller:phone,keyboardType:TextInputType.phone,decoration:InputDecoration(labelText:'Phone',hintText:controller.profile['phone']?.toString()??'')),const SizedBox(height:16),Obx(()=>FilledButton(onPressed:controller.saving.value?null:()async{final n=name.text.trim().isEmpty?(controller.profile['name']?.toString()??auth.user.value?.name??''):name.text.trim();final p=phone.text.trim().isEmpty?(controller.profile['phone']?.toString()??''):phone.text.trim();final ok=await controller.saveProfile(name: n, phone: p);if(ok)Get.snackbar('Profile updated','Your profile was saved.');},child:controller.saving.value?const CircularProgressIndicator(color:Colors.white):const Text('Save profile'))),const SizedBox(height:12),OutlinedButton.icon(onPressed:auth.logout,icon:const Icon(Icons.logout),label:const Text('Log out'))])));}}
